import React, { useState, useEffect, useRef } from "react";
import {
  ArrowRight, Package, Check, X, Phone, MapPin, Banknote,
  Wallet, Clock, AlertTriangle, Navigation, Loader2, Send, Bell, Truck,
} from "lucide-react";
import { api } from "./api.js";
import { useSession, useFetch, useAction } from "./hooks.js";

const LOGO_MARK = "data:image/png;base64,";
const LOGO_FULL = "data:image/png;base64,";

const money = (n) => `${Number(n || 0).toFixed(2)} د.ل`;

const STATUS_LABELS = {
  assigned_to_driver: "مسندة إليك", out_for_delivery: "في الطريق", delivered: "تم التسليم",
  ready_for_delivery: "جاهزة للتوصيل", closed: "مقفولة",
};
const statusLabel = (s) => STATUS_LABELS[s] || s;

const PAYMENT_LABELS = {
  cash: "نقدًا عند الاستلام", transfer: "حوالة مصرفية",
  deferred: "آجل معتمد من الإدارة", card: "بطاقة", pay_at_supplier: "الدفع عند المورد",
};

// نفضّل الإحداثيات المحفوظة (المحدّدة على الخريطة وقت التسجيل) عن النص الحر للعنوان،
// لأن النص وحده ممكن يوصل جوجل مابس لمكان مختلف أو عام أكتر من اللازم
const mapUrl = (lat, lng, address) =>
  lat != null && lng != null
    ? `https://maps.google.com/?q=${lat},${lng}`
    : `https://maps.google.com/?q=${encodeURIComponent(address || "")}`;

/* =================================================================== */

export default function JomlaDriverApp() {
  const { actor, loading, requestOtp, verifyOtp, logout } = useSession("employee");
  const [view, setView] = useState("orders");
  const [selectedId, setSelectedId] = useState(null);
  const [toast, setToast] = useState(null);

  function showToast(msg) {
    setToast(msg);
    window.clearTimeout(window.__drvToast);
    window.__drvToast = window.setTimeout(() => setToast(null), 2200);
  }

  if (loading) return <Shell><Centered><Loader2 className="spin" size={26} /><p>جارٍ التحميل…</p></Centered></Shell>;
  if (!actor) return <Shell><LoginView onRequestOtp={requestOtp} onVerify={verifyOtp} /></Shell>;

  // التطبيق مخصص لمندوبي التوصيل فقط
  if (actor.role !== "driver") {
    return (
      <Shell>
        <Centered>
          <AlertTriangle size={26} />
          <p>هذا التطبيق مخصص لمندوبي التوصيل.</p>
          <button className="btn-ghost" onClick={logout}>تسجيل الخروج</button>
        </Centered>
      </Shell>
    );
  }

  return (
    <Shell>
      <DriverShell
        actor={actor}
        view={view}
        setView={setView}
        selectedId={selectedId}
        setSelectedId={setSelectedId}
        onLogout={logout}
        showToast={showToast}
      />
      {toast && <div className="jomla-toast">{toast}</div>}
    </Shell>
  );
}

function DriverShell({ actor, view, setView, selectedId, setSelectedId, onLogout, showToast }) {
  const orders = useFetch((signal) => api.orders(undefined, signal), []);
  const cash = useFetch((signal) => api.driversCash(signal), []);

  const mine = cash.data?.find((d) => d.driver_id === actor.id);
  const cashInHand = Number(mine?.cash_in_hand ?? 0);

  function refreshAll() { orders.reload(); cash.reload(); }

  return (
    <>
      <TopBar
        view={view}
        cashInHand={cashInHand}
        onBack={() => setView("orders")}
        onCash={() => setView("cash")}
        onLogout={onLogout}
      />
      <main className="jomla-main">
        {view === "orders" && (
          <OrdersView
            actorName={actor.name}
            state={orders}
            cashInHand={cashInHand}
            onOpen={(id) => { setSelectedId(id); setView("orderDetail"); }}
            onGoCash={() => setView("cash")}
          />
        )}
        {view === "orderDetail" && (
          <OrderDetailView
            orderId={selectedId}
            orders={orders.data ?? []}
            onDone={(msg) => { refreshAll(); showToast(msg); setView("orders"); }}
          />
        )}
        {view === "cash" && (
          <CashView
            driverId={actor.id}
            orders={orders.data ?? []}
            cashInHand={cashInHand}
            onSettled={(total) => { refreshAll(); showToast(`تم تسليم ${money(total)} للشركة`); setView("orders"); }}
          />
        )}
      </main>
    </>
  );
}

/* ------------------------- عناصر مشتركة ------------------------- */

const Shell = ({ children }) => (
  <div dir="rtl" lang="ar" className="jomla-root"><Style />{children}</div>
);
const Centered = ({ children }) => <div className="center-state">{children}</div>;
const Spinner = ({ label = "جارٍ التحميل…" }) => (
  <Centered><Loader2 className="spin" size={22} /><p>{label}</p></Centered>
);
const ErrorState = ({ message, onRetry }) => (
  <Centered>
    <AlertTriangle size={22} /><p>{message}</p>
    {onRetry && <button className="btn-ghost" onClick={onRetry}>إعادة المحاولة</button>}
  </Centered>
);
const BrandMark = ({ size = 22 }) => (
  <img src={LOGO_MARK} alt="جملة" style={{ height: size, width: "auto", display: "block" }} />
);

/* --------------------------- الدخول --------------------------- */

function LoginView({ onRequestOtp, onVerify }) {
  const [step, setStep] = useState("phone");
  const [phone, setPhone] = useState("");
  const [digits, setDigits] = useState(["", "", "", ""]);
  const [seconds, setSeconds] = useState(0);
  const inputsRef = useRef([]);
  const send = useAction(onRequestOtp);
  const verify = useAction(onVerify);

  useEffect(() => {
    if (step !== "otp" || seconds <= 0) return;
    const t = setTimeout(() => setSeconds((s) => s - 1), 1000);
    return () => clearTimeout(t);
  }, [step, seconds]);
  useEffect(() => { if (step === "otp") inputsRef.current[0]?.focus(); }, [step]);

    async function handleSend() {
    if (phone.replace(/\D/g, "").length < 9) return;
    try {
      await send.run(phone);
      setSeconds(30);
      setStep("otp");
    } catch {
      // فشل الطلب (مثلاً حساب موقوف) — نفضل في شاشة إدخال الهاتف
      // ورسالة الخطأ هتظهر تلقائيًا تحت الحقل بسبب send.error
    }
  }

  function updateDigit(i, val) {
    const v = val.replace(/\D/g, "").slice(-1);
    const next = [...digits]; next[i] = v; setDigits(next);
    if (v && i < 3) inputsRef.current[i + 1]?.focus();
  }

  return (
    <div className="screen login-screen">
      <div className="brand-row"><img src={LOGO_FULL} alt="جملة" className="brand-logo-full" /></div>
      <p className="login-sub">تطبيق مندوبي التوصيل</p>

      {step === "phone" ? (
        <div className="login-card">
          <label className="field-label">رقم هاتف المندوب</label>
          <input className="field-input" placeholder="09XXXXXXXX" value={phone} dir="ltr"
            style={{ textAlign: "right" }} inputMode="numeric"
            onChange={(e) => setPhone(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && handleSend()} />
          {send.error && <p className="field-error">{send.error}</p>}
          <button className="btn-primary" onClick={handleSend} disabled={send.pending}>
            {send.pending ? "جارٍ الإرسال…" : "إرسال رمز التحقق"}
          </button>
        </div>
      ) : (
        <div className="login-card">
          <label className="field-label">رمز التحقق المُرسل إلى {phone}</label>
          <div className="otp-row" dir="ltr">
            {digits.map((d, i) => (
              <input key={i} ref={(el) => (inputsRef.current[i] = el)} className="otp-box"
                value={d} type="tel" inputMode="numeric" maxLength={1}
                autoComplete={i === 0 ? "one-time-code" : "off"}
                onChange={(e) => updateDigit(i, e.target.value)}
                onFocus={(e) => e.target.select()}
                onKeyDown={(e) => e.key === "Backspace" && !digits[i] && i > 0 && inputsRef.current[i - 1]?.focus()} />
            ))}
          </div>
          {verify.error && <p className="field-error">{verify.error}</p>}
          <button className="btn-primary" disabled={verify.pending || digits.join("").length < 4}
            onClick={() => verify.run(phone, digits.join("")).catch(() => {})}>
            {verify.pending ? "جارٍ التحقق…" : "تأكيد الدخول"}
          </button>
          <div className="otp-footer">
            <button className="link-btn" onClick={() => setStep("phone")}>تعديل الرقم</button>
            <button className="link-btn" disabled={seconds > 0} onClick={handleSend}>
              {seconds > 0 ? `إعادة الإرسال بعد ${seconds} ث` : "إعادة إرسال الرمز"}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

/* ------------------------- الشريط العلوي ------------------------- */

function NotificationBell() {
  const [open, setOpen] = useState(false);
  const { data, loading, reload } = useFetch(() => api.notifications(), []);

  useEffect(() => {
    const t = setInterval(reload, 30000);
    return () => clearInterval(t);
  }, []);

  const unreadCount = data?.unreadCount ?? 0;

  function markRead(n) {
    if (n.in_app_read_at) return;
    api.markNotificationRead(n.id).then(reload).catch(() => {});
  }
  function markAll() {
    api.markAllNotificationsRead().then(reload).catch(() => {});
  }

  return (
    <div style={{ position: "relative" }}>
      <button className="icon-btn" onClick={() => setOpen((o) => !o)} aria-label="الإشعارات">
        <Bell size={19} />
        {unreadCount > 0 && <span className="notif-badge">{unreadCount > 9 ? "9+" : unreadCount}</span>}
      </button>
      {open && (
        <div className="notif-panel">
          <div className="notif-panel-head">
            <span>الإشعارات</span>
            {unreadCount > 0 && <button className="link-btn" onClick={markAll}>تعليم الكل كمقروء</button>}
          </div>
          {loading ? <Spinner /> : !data?.notifications?.length ? (
            <p className="chat-empty">لا توجد إشعارات بعد</p>
          ) : (
            <div className="notif-list">
              {data.notifications.map((n) => (
                <div key={n.id} className={"notif-row" + (!n.in_app_read_at ? " notif-row-unread" : "")}
                  onClick={() => markRead(n)}>
                  <span className="notif-title">{n.title}</span>
                  <span className="notif-body">{n.body}</span>
                  <span className="notif-time">{new Date(n.created_at).toLocaleString("ar")}</span>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function TopBar({ view, cashInHand, onBack, onCash, onLogout }) {
  const inSub = view !== "orders";
  const titles = { orderDetail: "تفاصيل الطلبية", cash: "النقدية بحوزتي" };
  return (
    <header className="topbar">
      <div className="topbar-row">
        {inSub ? (
          <button className="icon-btn" onClick={onBack} aria-label="رجوع"><ArrowRight size={20} /></button>
        ) : (
          <div className="brand-chip"><BrandMark /><span>جملة — المندوب</span></div>
        )}
        {inSub && <span className="topbar-title">{titles[view]}</span>}
        <div className="topbar-actions">
          {!inSub && (
            <button className="cash-chip" onClick={onCash}>
              <Wallet size={15} />{money(cashInHand)}
            </button>
          )}
          <NotificationBell />
          <button className="icon-btn" onClick={onLogout} aria-label="خروج"><X size={18} /></button>
        </div>
      </div>
    </header>
  );
}

/* -------------------------- الطلبيات -------------------------- */

function OrdersView({ actorName, state, cashInHand, onOpen, onGoCash }) {
  const [tab, setTab] = useState("assigned");
  const { data, loading, error, reload } = state;

  const assigned = (data ?? []).filter((o) => o.status === "assigned_to_driver");
  const active = (data ?? []).filter((o) => o.status === "out_for_delivery");
  const done = (data ?? []).filter((o) => o.status === "delivered" || o.status === "closed");
  const list = tab === "assigned" ? assigned : tab === "active" ? active : done;

  return (
    <div className="screen">
      <p className="eyebrow-plain">أهلًا، {actorName}</p>

      <div className="stat-grid">
        <div className="stat-box"><span>مسندة إليك</span><b>{assigned.length}</b></div>
        <div className="stat-box"><span>في الطريق</span><b>{active.length}</b></div>
        <div className="stat-box stat-box-debt"><span>نقدية بحوزتك</span><b>{money(cashInHand)}</b></div>
      </div>

      {cashInHand > 0 && (
        <button className="alert-banner" onClick={onGoCash}>
          <AlertTriangle size={16} />
          <span>لديك {money(cashInHand)} لم تُسلَّم للشركة بعد</span>
        </button>
      )}

      <div className="chip-row">
        <button className={"chip" + (tab === "assigned" ? " chip-active" : "")} onClick={() => setTab("assigned")}>
          مسندة إليك ({assigned.length})
        </button>
        <button className={"chip" + (tab === "active" ? " chip-active" : "")} onClick={() => setTab("active")}>
          في الطريق ({active.length})
        </button>
        <button className={"chip" + (tab === "done" ? " chip-active" : "")} onClick={() => setTab("done")}>
          تم التسليم ({done.length})
        </button>
      </div>

      {loading ? <Spinner />
       : error ? <ErrorState message={error} onRetry={reload} />
       : !list.length ? (
         <Centered>
           <Package size={24} />
           <p>{tab === "assigned" ? "لا توجد طلبيات مسندة إليك حاليًا"
              : tab === "active" ? "لا توجد طلبيات في الطريق" : "لا توجد طلبيات مسلّمة بعد"}</p>
         </Centered>
       ) : (
        <div className="order-list">
          {list.map((o) => (
            <button className="order-card" key={o.id} onClick={() => onOpen(o.id)}>
              <div className="order-card-top">
                <span className="order-card-id">{o.order_number}</span>
                <span className={"status-pill" + (o.status !== "assigned_to_driver" && o.status !== "out_for_delivery" ? " status-pill-done" : "")}>
                  {statusLabel(o.status)}
                </span>
              </div>
              <span className="order-card-customer">{o.customer_name}</span>
              {o.address && (
                <span className="order-card-address"><MapPin size={12} /> {o.address}</span>
              )}
              <div className="order-card-bottom">
                <span className="order-card-items">{String(o.created_at).slice(0, 10)}</span>
                {Number(o.cod_amount) > 0 && (
                  <span className={"collect-tag" + (o.cod_collected ? " collect-tag-done" : "")}>
                    {o.cod_collected ? "تم التحصيل" : `يُحصّل ${money(o.cod_amount)}`}
                  </span>
                )}
              </div>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

/* ----------------------- تفاصيل الطلبية ----------------------- */

function OrderDetailView({ orderId, orders, onDone }) {
  const [confirming, setConfirming] = useState(false);
  const summary = orders.find((o) => o.id === orderId);
  const detail = useFetch((signal) => api.order(orderId, signal), [orderId]);
  const deliver = useAction((collected) => api.deliverOrder(orderId, collected));
  const start = useAction(() => api.startDelivery(orderId));

  if (detail.loading) return <Spinner />;
  if (detail.error) return <ErrorState message={detail.error} onRetry={detail.reload} />;

  const order = detail.data ?? summary;
  if (!order) return <Centered><Package size={24} /><p>تعذّر العثور على الطلبية</p></Centered>;

  const assignedOnly = order.status === "assigned_to_driver";
  const active = order.status === "out_for_delivery";
  const cod = Number(order.cod_amount || 0);
  const items = (order.suppliers ?? []).flatMap((s) =>
    (s.items ?? []).map((i) => ({ ...i, supplier_name: s.supplier_name }))
  );

  async function confirm(collected) {
    await deliver.run(collected)
      .then(() => onDone(collected ? "تم تأكيد التسليم واستلام المبلغ" : "تم تأكيد التسليم بدون تحصيل"))
      .catch(() => {});
  }

  return (
    <div className="screen">
      <div className="detail-head">
        <span className="order-card-id">{order.order_number}</span>
        <span className={"status-pill" + (!active ? " status-pill-done" : "")}>{statusLabel(order.status)}</span>
      </div>

      {items.length > 0 && (order.suppliers ?? []).length > 0 && (
        <>
          <h2 className="subsection-heading">مواقع الاستلام ({(order.suppliers ?? []).length} مورد)</h2>
          {(order.suppliers ?? []).map((s) => (
            <div className="info-card" key={s.id}>
              <h3>{s.supplier_name}</h3>
              {s.supplier_address && <p className="info-line"><MapPin size={13} /> {s.supplier_address}</p>}
              <div className="contact-row">
                {s.supplier_phone && (
                  <a className="contact-btn" href={`tel:${s.supplier_phone}`}>
                    <Phone size={15} /> اتصال بالمورد
                  </a>
                )}
                {(s.supplier_latitude != null || s.supplier_address) && (
                  <a className="contact-btn" target="_blank" rel="noreferrer"
                    href={mapUrl(s.supplier_latitude, s.supplier_longitude, s.supplier_address)}>
                    <Navigation size={15} /> فتح الخريطة
                  </a>
                )}
              </div>
            </div>
          ))}
        </>
      )}

      <h2 className="subsection-heading">موقع التسليم</h2>
      <div className="info-card">
        <h3>{order.customer_name}</h3>
        {order.address && <p className="info-line"><MapPin size={13} /> {order.address}</p>}
        <div className="contact-row">
          {order.customer_phone && (
            <a className="contact-btn" href={`tel:${order.customer_phone}`}>
              <Phone size={15} /> اتصال بالعميل
            </a>
          )}
          {(order.customer_latitude != null || order.address) && (
            <a className="contact-btn" target="_blank" rel="noreferrer"
              href={mapUrl(order.customer_latitude, order.customer_longitude, order.address)}>
              <Navigation size={15} /> فتح الخريطة
            </a>
          )}
        </div>
        <p className="info-line" style={{ marginTop: 10, marginBottom: 0 }}>
          <Banknote size={13} /> طريقة الدفع: {PAYMENT_LABELS[order.payment_method] || order.payment_method}
        </p>
      </div>

      <h2 className="subsection-heading">الأصناف</h2>
      <div className="items-block">
        {items.map((i) => (
          <div className="item-line" key={i.id}>
            <div className="item-line-main">
              <span className="item-name">{i.product_name}</span>
              <span className="item-supplier">{i.supplier_name}</span>
            </div>
            <span className="item-qty">{i.qty_confirmed ?? i.qty_requested} {i.unit}</span>
          </div>
        ))}
        {!items.length && <div className="item-line"><span className="item-name">—</span></div>}
      </div>

      {cod > 0 && (
        <div className={"collect-box" + (order.cod_collected ? " collect-box-done" : "")}>
          <Banknote size={18} />
          <div>
            <span className="collect-box-label">
              {order.cod_collected ? "المبلغ المحصّل من العميل" : "المبلغ المطلوب تحصيله عند التسليم"}
            </span>
            <b>{money(cod)}</b>
            {order.payment_method === "deferred" && !order.cod_collected && (
              <span className="collect-box-note">طلبية آجلة — حصّل هذا المبلغ فقط</span>
            )}
          </div>
        </div>
      )}

      {deliver.error && <p className="field-error">{deliver.error}</p>}
      {start.error && <p className="field-error">{start.error}</p>}

      {assignedOnly ? (
        <button className="btn-primary btn-big" disabled={start.pending}
          onClick={() => start.run().then(() => onDone("تم بدء التوصيل")).catch(() => {})}>
          <Truck size={18} style={{ verticalAlign: "-4px", marginLeft: 8 }} />
          {start.pending ? "جارٍ البدء…" : "بدء التوصيل"}
        </button>
      ) : active ? (
        confirming ? (
          <div className="confirm-box">
            <p className="confirm-question">
              {cod > 0 ? `هل استلمت ${money(cod)} من العميل؟` : "تأكيد تسليم الطلبية للعميل؟"}
            </p>
            {cod > 0 ? (
              <>
                <button className="btn-primary" disabled={deliver.pending} onClick={() => confirm(true)}>
                  <Check size={16} style={{ verticalAlign: "-3px", marginLeft: 6 }} />
                  نعم، سلّمت واستلمت المبلغ
                </button>
                <button className="btn-ghost" disabled={deliver.pending} onClick={() => confirm(false)}>
                  سلّمت بدون تحصيل مبلغ
                </button>
              </>
            ) : (
              <button className="btn-primary" disabled={deliver.pending} onClick={() => confirm(false)}>
                <Check size={16} style={{ verticalAlign: "-3px", marginLeft: 6 }} /> تأكيد التسليم
              </button>
            )}
            <button className="btn-ghost" onClick={() => setConfirming(false)}>تراجع</button>
          </div>
        ) : (
          <button className="btn-primary btn-big" onClick={() => setConfirming(true)}>
            <Check size={18} style={{ verticalAlign: "-4px", marginLeft: 8 }} /> تأكيد تسليم الطلبية
          </button>
        )
      ) : (
        <div className="done-stamp"><Check size={16} /><span>تم تسليم هذه الطلبية</span></div>
      )}

      <h2 className="subsection-heading" style={{ marginTop: 20 }}>الدردشة مع العميل</h2>
      <DriverChatPanel orderId={order.id} />
    </div>
  );
}

function DriverChatPanel({ orderId }) {
  const { data, loading, error, reload } = useFetch(() => api.orderMessages(orderId), [orderId]);
  const [draft, setDraft] = useState("");
  const send = useAction(() => api.sendOrderMessage(orderId, { body: draft.trim() }));

  function submit() {
    if (!draft.trim()) return;
    send.run().then(() => { setDraft(""); reload(); }).catch(() => {});
  }

  return (
    <div className="chat-panel">
      <div className="chat-thread">
        {loading ? <Spinner label="جارٍ التحميل…" />
         : error ? <ErrorState message={error} onRetry={reload} />
         : !data?.length ? <p className="chat-empty">راسل العميل هنا لو احتجت توضيح موقع التسليم أو أي تفصيل.</p>
         : data.map((m, i) => (
            <div className={"chat-bubble " + (m.sender_type === "employee" ? "chat-bubble-user" : "chat-bubble-support")} key={i}>
              <span>{m.body}</span>
              <span className="chat-time">{new Date(m.created_at).toLocaleTimeString("ar", { hour: "2-digit", minute: "2-digit" })}</span>
            </div>
          ))}
      </div>
      <div className="chat-input-row">
        <input className="chat-input" placeholder="اكتب رسالتك..." value={draft}
          onChange={(e) => setDraft(e.target.value)} onKeyDown={(e) => e.key === "Enter" && submit()} />
        <button className="chat-send" onClick={submit} disabled={send.pending} aria-label="إرسال"><Send size={17} /></button>
      </div>
      {send.error && <p className="field-error">{send.error}</p>}
    </div>
  );
}

/* --------------------------- النقدية --------------------------- */

function CashView({ driverId, orders, cashInHand, onSettled }) {
  const settle = useAction(() => api.settleDriver(driverId));

  const pending = orders.filter((o) => o.cod_collected && !o.cod_settled);
  const settled = orders.filter((o) => o.cod_settled);

  return (
    <div className="screen">
      <div className="cash-hero">
        <Wallet size={26} />
        <span>النقدية التي بحوزتك الآن</span>
        <b>{money(cashInHand)}</b>
      </div>

      {settle.error && <p className="field-error">{settle.error}</p>}

      {cashInHand > 0 ? (
        <button className="btn-primary btn-big" disabled={settle.pending}
          onClick={() => settle.run().then((r) => onSettled(r.total)).catch(() => {})}>
          <Check size={18} style={{ verticalAlign: "-4px", marginLeft: 8 }} />
          {settle.pending ? "جارٍ التسليم…" : "تسليم المبلغ كامل للشركة"}
        </button>
      ) : (
        <div className="done-stamp"><Check size={16} /><span>لا توجد مبالغ معلّقة — حسابك مسوّى</span></div>
      )}

      <h2 className="subsection-heading" style={{ marginTop: 22 }}>
        مبالغ بانتظار التسليم ({pending.length})
      </h2>
      {!pending.length ? (
        <Centered><Banknote size={22} /><p>لا توجد مبالغ معلّقة</p></Centered>
      ) : (
        <div className="cash-list">
          {pending.map((o) => (
            <div className="cash-row" key={o.id}>
              <div>
                <span className="cash-row-id">{o.order_number}</span>
                <span className="cash-row-customer">{o.customer_name}</span>
              </div>
              <b>{money(o.cod_amount)}</b>
            </div>
          ))}
        </div>
      )}

      <h2 className="subsection-heading" style={{ marginTop: 22 }}>
        مبالغ تم تسليمها سابقًا ({settled.length})
      </h2>
      {!settled.length ? (
        <Centered><Clock size={22} /><p>لا يوجد سجل بعد</p></Centered>
      ) : (
        <div className="cash-list">
          {settled.map((o) => (
            <div className="cash-row cash-row-done" key={o.id}>
              <div>
                <span className="cash-row-id">{o.order_number}</span>
                <span className="cash-row-customer">{o.customer_name}</span>
              </div>
              <b>{money(o.cod_amount)}</b>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

